#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int q;
    cin >> q;

    vector<int> x(q);
    vector<long long> y(q);

    int maxX = 0;
    for (int i = 0; i < q; ++i) {
        cin >> x[i] >> y[i];
        maxX = max(maxX, x[i]);
    }

    const string a = "What are you doing at the end of the world? Are you busy? Will you save us?";
    const string b = "What are you doing while sending \"";
    const string c = "\"? Are you busy? Will you send \"";
    const string d = "\"?";
    const long long INF = LLONG_MAX;

    vector<long long> len(maxX + 1);
    len[0] = a.size();

    int saturated = -1;
    for (int i = 1; i <= maxX; ++i) {
        __int128 value = (__int128)2 * len[i - 1] + b.size() + c.size() + d.size();
        if (value >= INF) {
            len[i] = INF;
            if (saturated == -1) saturated = i;
        } else {
            len[i] = static_cast<long long>(value);
        }
    }

    auto getCharacter = [&](int n, long long k) {
        if (saturated != -1 && n > saturated) {
            long long levels = n - saturated;
            long long prefixes = (k - 1) / static_cast<long long>(b.size());

            if (prefixes < levels)
                return b[(k - 1) % b.size()];

            k -= levels * static_cast<long long>(b.size());
            n = saturated;
        }

        while (n > 0) {
            if (k <= static_cast<long long>(b.size()))
                return b[k - 1];
            k -= b.size();

            if (k <= len[n - 1]) {
                --n;
                continue;
            }
            k -= len[n - 1];

            if (k <= static_cast<long long>(c.size()))
                return c[k - 1];
            k -= c.size();

            if (k <= len[n - 1]) {
                --n;
                continue;
            }
            k -= len[n - 1];

            if (k <= static_cast<long long>(d.size()))
                return d[k - 1];

            return '.';
        }

        return k <= static_cast<long long>(a.size()) ? a[k - 1] : '.';
    };

    for (int i = 0; i < q; ++i)
        cout << getCharacter(x[i], y[i]);

    return 0;
}

