int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int q;
    cin >> q;

    vector<int> n(q);
    vector<unsigned long long> k(q);
    int maxN = 0;
    unsigned long long maxK = 1;

    for (int i = 0; i < q; ++i) {
        cin >> n[i] >> k[i];
        maxN = max(maxN, n[i]);
        maxK = max(maxK, k[i]);
    }

    const string base = "What are you doing at the end of the world? Are you busy? Will you save us?";
    const string prefix = "What are you doing while sending \"";
    const string middle = "\"? Are you busy? Will you send \"";
    const string suffix = "\"?";

    vector<unsigned long long> len(maxN + 1);
    len[0] = min<unsigned long long>(base.size(), maxK);

    int saturated = (len[0] == maxK ? 0 : -1);

    for (int i = 1; i <= maxN; ++i) {
        __int128 value = (__int128)prefix.size() + middle.size() + suffix.size()
                       + (__int128)2 * len[i - 1];
        len[i] = value >= maxK ? maxK : (unsigned long long)value;
        if (saturated == -1 && len[i] == maxK)
            saturated = i;
    }

    auto getCharacter = [&](int level, unsigned long long pos) {
        while (true) {
            if (pos == 0 || pos > len[level])
                return '.';

            if (level == 0)
                return pos <= base.size() ? base[pos - 1] : '.';

            if (saturated >= 0 && level > saturated) {
                if (pos <= prefix.size())
                    return prefix[pos - 1];

                unsigned long long skip = min<unsigned long long>(
                    level - saturated,
                    (pos - 1) / prefix.size()
                );

                level -= static_cast<int>(skip);
                pos -= skip * prefix.size();
                continue;
            }

            if (pos <= prefix.size())
                return prefix[pos - 1];
            pos -= prefix.size();

            if (pos <= len[level - 1]) {
                --level;
                continue;
            }
            pos -= len[level - 1];

            if (pos <= middle.size())
                return middle[pos - 1];
            pos -= middle.size();

            if (pos <= len[level - 1]) {
                --level;
                continue;
            }
            pos -= len[level - 1];

            if (pos <= suffix.size())
                return suffix[pos - 1];

            return '.';
        }
    };

    for (int i = 0; i < q; ++i)
        cout << getCharacter(n[i], k[i]);

    return 0;
}

